// T-359 (S3) acceptance — the plan batch import off the T-358 template:
// create-only, references generated by the naming scheme in file order, a
// reference-like column ignored, role columns dropped with a stated notice,
// and a whole-file verdict whose failures name the Excel row the user sees.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { eq } from 'drizzle-orm';
import type { PlanImportError, PlanImportResult } from '@infora/contracts';
import { createDb, hashPassword, schema as s } from '@infora/db';
import { buildApp } from './app';
import { fakeRouter } from './test-router';
import { buildXlsx } from './xlsx';

const { db, pool } = createDb();
const app = buildApp({ db, sessionSecret: 'test-secret', router: fakeRouter() });

const stamp = Date.now();
const password = 'pw-t359';
let projectId: string;
let ownerCookie: string;
let superCookie: string;
let memberCookie: string;

async function makeUser(name: string, organisationId: string, elevated = false) {
  const [user] = await db
    .insert(s.users)
    .values({ name, email: `${name}-${stamp}@test.local`, organisationId })
    .returning();
  await db.insert(s.userCredentials).values({ userId: user!.id, passwordHash: hashPassword(password) });
  await db.insert(s.participants).values({ userId: user!.id, projectId, elevated });
  return user!;
}
async function session(email: string): Promise<string> {
  const res = await app.request('/auth/session', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  return res.headers.get('set-cookie')!.split(';')[0]!;
}

beforeAll(async () => {
  const [oA] = await db.insert(s.organisations).values({ name: 't359 owner' }).returning();
  const [oB] = await db.insert(s.organisations).values({ name: 't359 consult' }).returning();
  const [project] = await db
    .insert(s.projects)
    .values({ name: 't359 project', ownerOrganisationId: oA!.id })
    .returning();
  projectId = project!.id;
  await db.insert(s.memberships).values([
    { organisationId: oA!.id, projectId, role: 'owner' },
    { organisationId: oB!.id, projectId, role: 'member' },
  ]);
  ownerCookie = await session((await makeUser('t359-oona', oA!.id, true)).email);
  superCookie = await session((await makeUser('t359-beth', oB!.id, true)).email);
  memberCookie = await session((await makeUser('t359-mona', oB!.id)).email);
  // the 4-field scheme: three coded fields + serial; discipline doubles as metadata? no — code
  await app.request(`/projects/${projectId}/naming-scheme`, {
    method: 'PUT',
    headers: { cookie: ownerCookie, 'content-type': 'application/json' },
    body: JSON.stringify({
      separator: '-',
      fields: [
        { key: 'project', label: 'Project', inCode: true, allowedValues: ['WA'] },
        { key: 'originator', label: 'Originator', inCode: true, isOriginator: true, allowedValues: ['BB', 'TM'] },
        { key: 'discipline', label: 'Discipline', inCode: true, allowedValues: ['GEO', 'ENV'] },
        { key: 'serial', label: 'Serial', inCode: true, isSerial: true, width: 3 },
        { key: 'suitability', label: 'Suitability', type: 'select', inCode: false, allowedValues: ['S0', 'S1'] },
        { key: 'authors', label: 'Author(s)', type: 'people', role: 'author' },
      ],
    }),
  });
});

afterAll(async () => {
  await pool.end();
});

function importFile(cookie: string, rows: (string | null)[][]) {
  const form = new FormData();
  const bytes = buildXlsx([{ name: 'Deliverables', rows }]);
  form.append('file', new File([new Uint8Array(bytes)], 'plan.xlsx'));
  return app.request(`/projects/${projectId}/plan/import`, {
    method: 'POST',
    headers: { cookie },
    body: form,
  });
}

describe('the plan batch import (T-359, S3)', () => {
  it('creates rows in file order with sequentially generated references; role and reference-like columns are ignored and named', async () => {
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline', 'Suitability', 'Author(s)', 'Reference'],
      ['Ground investigation', 'WA', 'BB', 'GEO', 'S0', 'A. Person', 'IGNORED-999'],
      ['Baseline report', 'WA', 'BB', 'GEO', '', 'B. Person', 'IGNORED-998'],
      ['Ecology chapter', 'WA', 'BB', 'ENV', 'S1', '', ''],
    ]);
    expect(res.status).toBe(201);
    const body = (await res.json()) as PlanImportResult;
    expect(body.created).toBe(3);
    // file order IS numbering order — the reference-like column played no part
    expect(body.items.map((r) => r.documentReference)).toEqual([
      'WA-BB-GEO-001',
      'WA-BB-GEO-002',
      'WA-BB-ENV-001',
    ]);
    expect(body.items.map((r) => r.workItem?.title)).toEqual([
      'Ground investigation',
      'Baseline report',
      'Ecology chapter',
    ]);
    // attribute metadata rides; the role column was dropped with a stated notice
    expect(body.items[0]!.metadata['suitability']).toBe('S0');
    // discipline is a code field surfaced at-a-glance (T-178) — the import
    // copies it into metadata exactly as the single-create modal does
    expect(body.items[0]!.metadata['discipline']).toBe('GEO');
    expect(body.items[0]!.metadata['authors']).toBeUndefined();
    expect(body.ignoredColumns.some((col) => col.startsWith('Author(s)'))).toBe(true);
    expect(body.ignoredColumns).toContain('Reference');
  });

  const projectRowCount = async () =>
    (await db.select().from(s.containers).where(eq(s.containers.projectId, projectId))).length;

  it('refuses the whole file when any row fails, naming the Excel row — and creates nothing', async () => {
    const before = await projectRowCount();
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline'],
      ['Good row', 'WA', 'BB', 'GEO'],
      ['', 'WA', 'BB', 'GEO'], // row 3: no title
      ['Bad code', 'WA', 'BB', 'ZZZ'], // row 4: discipline outside the scheme
    ]);
    expect(res.status).toBe(400);
    const body = (await res.json()) as PlanImportError;
    expect(body.detail).toBe('rows');
    expect(body.failures).toEqual([
      { row: 3, problem: 'Title is empty' },
      { row: 4, problem: 'Discipline: "ZZZ" is not one of the scheme\'s codes' },
    ]);
    expect(await projectRowCount()).toBe(before);
  });

  it('is create-only against an existing plan — importing again adds rows, never amends', async () => {
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline'],
      ['Ground investigation', 'WA', 'BB', 'GEO'],
    ]);
    expect(res.status).toBe(201);
    const body = (await res.json()) as PlanImportResult;
    // same title, same series: a NEW row with the next serial, not an update
    expect(body.items[0]!.documentReference).toBe('WA-BB-GEO-003');
  });

  it('refuses a file with no Title column, an unreadable file, and an empty grid', async () => {
    const noTitle = await importFile(superCookie, [['Project', 'Originator', 'Discipline'], ['WA', 'BB', 'GEO']]);
    expect(noTitle.status).toBe(400);
    expect(((await noTitle.json()) as PlanImportError).detail).toBe('title_column_required');

    const form = new FormData();
    form.append('file', new File([new Uint8Array(Buffer.from('not a workbook'))], 'plan.xlsx'));
    const unreadable = await app.request(`/projects/${projectId}/plan/import`, {
      method: 'POST',
      headers: { cookie: superCookie },
      body: form,
    });
    expect(unreadable.status).toBe(400);
    expect(((await unreadable.json()) as PlanImportError).detail).toBe('unreadable_file');

    const empty = await importFile(superCookie, [['Title', 'Project', 'Originator', 'Discipline']]);
    expect(empty.status).toBe(400);
    expect(((await empty.json()) as PlanImportError).detail).toBe('no_rows');
  });

  it('binds metadata enums exactly as code enums — the template advertises the dropdown, the import enforces it', async () => {
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline', 'Suitability'],
      ['Junk suitability', 'WA', 'BB', 'GEO', 'BANANA'],
    ]);
    expect(res.status).toBe(400);
    const body = (await res.json()) as PlanImportError;
    expect(body.failures).toEqual([
      { row: 2, problem: 'Suitability: "BANANA" is not one of the scheme\'s codes' },
    ]);
  });

  it('refuses two columns mapping to one field rather than racing last-wins', async () => {
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline', 'Title'],
      ['A row', 'WA', 'BB', 'GEO', ''],
    ]);
    expect(res.status).toBe(400);
    expect(((await res.json()) as PlanImportError).detail).toBe('duplicate_columns');
  });

  it('answers a composed reference colliding with a hand-created row as a 409 conflict, creating nothing', async () => {
    // the ENV series allocated 001 above, so the next import composes -002;
    // reserve exactly that reference by hand first (free string, T-118 path)
    const reserve = await app.request(`/projects/${projectId}/plan`, {
      method: 'POST',
      headers: { cookie: superCookie, 'content-type': 'application/json' },
      body: JSON.stringify({ documentReference: 'WA-BB-ENV-002', title: 'Hand-reserved' }),
    });
    expect(reserve.status).toBe(201);
    const before = await projectRowCount();
    const res = await importFile(superCookie, [
      ['Title', 'Project', 'Originator', 'Discipline'],
      ['Collides', 'WA', 'BB', 'ENV'],
    ]);
    expect(res.status).toBe(409);
    expect(((await res.json()) as PlanImportError).detail).toBe('reference_exists');
    expect(await projectRowCount()).toBe(before);
  });

  it('is a super-user act: an ordinary member is refused, and the import lands on the importer\'s own plan', async () => {
    const denied = await importFile(memberCookie, [
      ['Title', 'Project', 'Originator', 'Discipline'],
      ['Nope', 'WA', 'BB', 'GEO'],
    ]);
    expect(denied.status).toBe(403);
    expect(((await denied.json()) as PlanImportError).detail).toBe('super_user_required');

    // the owner's import produces owner-org rows — its own serial allocation
    const owner = await importFile(ownerCookie, [
      ['Title', 'Project', 'Originator', 'Discipline'],
      ['Owner reference doc', 'WA', 'TM', 'GEO'],
    ]);
    expect(owner.status).toBe(201);
    expect(((await owner.json()) as PlanImportResult).items[0]!.documentReference).toBe('WA-TM-GEO-001');
  });
});
